package pe.metago;
import android.app.*;import android.os.*;import android.content.*;import android.content.res.ColorStateList;import android.graphics.Color;import android.graphics.Typeface;import android.graphics.drawable.GradientDrawable;import android.view.*;import android.widget.*;import android.media.*;import org.json.*;import java.util.*;import java.text.*;
public class MainActivity extends Activity {
 android.content.SharedPreferences p; LinearLayout root; JSONArray entries; long goal,daily; int purple=0xffa78bfa; ToneGenerator tone;
 public void onCreate(Bundle b){super.onCreate(b);p=getSharedPreferences("meta",0);if(android.os.Build.VERSION.SDK_INT>=33 && checkSelfPermission("android.permission.POST_NOTIFICATIONS")!=0)requestPermissions(new String[]{"android.permission.POST_NOTIFICATIONS"},1);show();}
 long total(){long s=0;for(int i=0;i<entries.length();i++)s+=entries.optJSONObject(i).optLong("amount");return s;}
 String money(long n){return String.format(Locale.US,"S/ %,.2f",n/100.0);}
 long parse(EditText e){try{return new java.math.BigDecimal(e.getText().toString().trim().replace(',','.')).movePointRight(2).longValueExact();}catch(Exception x){return -1;}}
 TextView text(String s,int size,int color){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(color);t.setPadding(0,8,0,8);root.addView(t);return t;}
 void button(String s,Runnable r){Button b=new Button(this);b.setText(s);b.setAllCaps(false);b.setTextColor(Color.WHITE);b.setBackgroundTintList(ColorStateList.valueOf(0xff6941c6));root.addView(b);b.setOnClickListener(v->r.run());}
 EditText field(String s){EditText e=new EditText(this);e.setInputType(8194);e.setText(s);return e;}
 void save(){p.edit().putString("entries",entries.toString()).apply();show();}
 void show(){goal=p.getLong("goal",200000);daily=p.getLong("daily",1500);try{entries=new JSONArray(p.getString("entries","[]"));}catch(Exception e){entries=new JSONArray();}long sum=total(),left=Math.max(0,goal-sum);ScrollView scroll=new ScrollView(this);scroll.setBackgroundColor(0xff151126);root=new LinearLayout(this);root.setOrientation(1);root.setPadding(32,48,32,48);scroll.addView(root);setContentView(scroll);text("✦ MetaGO",32,purple).setTypeface(null,Typeface.BOLD);text("TU FUTURO EMPIEZA HOY",13,purple);text(money(sum),40,Color.WHITE).setTypeface(null,Typeface.BOLD);text("Meta  "+money(goal),18,Color.WHITE);ProgressBar bar=new ProgressBar(this,null,android.R.attr.progressBarStyleHorizontal);bar.setMax(1000);bar.setProgress((int)Math.min(1000,1000.0*sum/goal));bar.setProgressTintList(ColorStateList.valueOf(purple));root.addView(bar,new LinearLayout.LayoutParams(-1,28));text(String.format(Locale.US,"%.1f%% completado",100.0*sum/goal),16,purple);text("Faltan "+money(left)+"  ·  "+((left+daily-1)/daily)+" días estimados",18,Color.WHITE);text("Aporte sugerido: "+money(daily),16,Color.WHITE);button("＋ Registrar depósito",()->deposit(-1));button("🔔 Configurar recordatorio",()->new TimePickerDialog(this,(v,h,m)->{p.edit().putInt("hour",h).putInt("minute",m).apply();Reminder.schedule(this);show();},p.getInt("hour",20),p.getInt("minute",0),true).show());if(p.contains("hour"))text(String.format(Locale.US,"Recordatorio diario ~%02d:%02d",p.getInt("hour",20),p.getInt("minute",0)),14,purple);button("⚙ Editar meta y aporte",()->settings());text("🏆 Logros",23,purple);for(int n:new int[]{100,500,1000,2000})text((sum>=n*100L?"★ ":"☆ ")+money(n*100L),17,sum>=n*100L?0xffffd166:Color.LTGRAY);text("Historial",23,purple);for(int i=entries.length()-1;i>=0;i--){final int j=i;JSONObject o=entries.optJSONObject(i);button(o.optString("date")+"  + "+money(o.optLong("amount")),()->new AlertDialog.Builder(this).setItems(new String[]{"Editar","Eliminar"},(d,k)->{if(k==0)deposit(j);else new AlertDialog.Builder(this).setMessage("¿Eliminar este registro?").setPositiveButton("Eliminar",(a,b)->{entries.remove(j);save();}).setNegativeButton("Cancelar",null).show();}).show());}text("Registro manual · No realiza transferencias bancarias",13,Color.LTGRAY);}
 void deposit(int i){EditText e=field(String.format(Locale.US,"%.2f",(i<0?daily:entries.optJSONObject(i).optLong("amount"))/100.0));AlertDialog d=new AlertDialog.Builder(this).setTitle("Monto realmente ahorrado").setView(e).setNegativeButton("Cancelar",null).setPositiveButton("Guardar",null).create();d.setOnShowListener(v->d.getButton(-1).setOnClickListener(w->{long n=parse(e);if(n<=0||n>100000000){e.setError("Monto inválido");return;}long before=total();try{JSONObject o=new JSONObject();o.put("amount",n);o.put("date",i<0?new SimpleDateFormat("dd/MM/yyyy",Locale.US).format(new Date()):entries.optJSONObject(i).optString("date"));if(i<0)entries.put(o);else entries.put(i,o);long after=total();save();d.dismiss();if(i<0){root.setAlpha(.5f);root.animate().alpha(1).setDuration(500).start();try{ToneGenerator t=new ToneGenerator(AudioManager.STREAM_MUSIC,45);t.startTone(ToneGenerator.TONE_PROP_ACK,180);new Handler().postDelayed(()->t.release(),300);}catch(Exception ex){}if(before<goal&&after>=goal)new AlertDialog.Builder(this).setTitle("🏆 ¡Meta completada!").setMessage("¡Lo conseguiste!").setPositiveButton("Genial",null).show();}}catch(Exception ex){e.setError("No se pudo guardar");}}));d.show();}
 void settings(){LinearLayout l=new LinearLayout(this);l.setOrientation(1);EditText g=field(String.valueOf(goal/100.0)),a=field(String.valueOf(daily/100.0));g.setHint("Meta");a.setHint("Aporte diario");l.addView(g);l.addView(a);AlertDialog d=new AlertDialog.Builder(this).setTitle("Meta y aporte diario (soles)").setView(l).setNegativeButton("Cancelar",null).setPositiveButton("Guardar",null).create();d.setOnShowListener(v->d.getButton(-1).setOnClickListener(w->{long x=parse(g),y=parse(a);if(x<=0||y<=0||x>100000000||y>100000000){g.setError("Revisa los montos");return;}p.edit().putLong("goal",x).putLong("daily",y).apply();d.dismiss();show();}));d.show();}
}